import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import '../styles/LoginPage.css';

const LoginPage = () => {
    const [formData, setFormData] = useState({
        name: '',
        password: '',
        remember: false
    });
    const [showPassword, setShowPassword] = useState(false);
    const [errors, setErrors] = useState({});
    const navigate = useNavigate();

    const togglePasswordVisibility = () => {
        setShowPassword(!showPassword);
    };

    const validateForm = () => {
        const newErrors = {};
        
        if (!formData.name.trim()) {
            newErrors.name = "Ім'я обов'язкове";
        }
        
        if (!formData.password) {
            newErrors.password = "Пароль обов'язковий";
        }
        
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        setFormData({
            ...formData,
            [name]: type === 'checkbox' ? checked : value
        });
        
        // Очищаем ошибку при изменении поля
        if (errors[name]) {
            setErrors({
                ...errors,
                [name]: null
            });
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        
        if (validateForm()) {
            // Здесь можно добавить логику отправки данных на сервер
            alert("Вхід виконано успішно!");
            // Перенаправление на главную страницу после успешного входа
            navigate('/');
        } else {
            alert("Будь ласка, заповніть усі поля.");
        }
    };

    const goToRegister = () => {
        navigate('/register');
    };

    const goBack = () => {
        navigate('/');
    };

    return (
        <div className="login-page">
            <a href="#" className="back" onClick={goBack}>← Назад</a>
            <div className="form-container">
                <h2>Вхід</h2>
                <form onSubmit={handleSubmit}>
                    <input
                        type="text"
                        name="name"
                        placeholder="Ім'я та прізвище"
                        value={formData.name}
                        onChange={handleChange}
                        className={errors.name ? 'invalid' : ''}
                    />
                    <div className="password-field">
                        <input
                            type={showPassword ? "text" : "password"}
                            name="password"
                            placeholder="Пароль"
                            value={formData.password}
                            onChange={handleChange}
                            className={errors.password ? 'invalid' : ''}
                        />
                        <span onClick={togglePasswordVisibility}>
                            {showPassword ? '🙈' : '👁️'}
                        </span>
                    </div>
                    <div className="checkbox">
                        <input
                            type="checkbox"
                            name="remember"
                            id="remember"
                            checked={formData.remember}
                            onChange={handleChange}
                        />
                        <label htmlFor="remember">Запам'ятати мене</label>
                    </div>
                    <button type="submit">Увійти</button>
                </form>
                <div className="or"><span>Або</span></div>
                <div className="social-btns">
                    <button>
                        <img src="https://www.svgrepo.com/show/475656/google-color.svg" alt="G" />
                        Продовжити з Google
                    </button>
                    <button>
                        <img src="https://www.svgrepo.com/show/475647/facebook-color.svg" alt="FB" />
                        Продовжити з Facebook
                    </button>
                </div>
                <div className="register-link">
                    Ще не маєте акаунта? <a href="#" onClick={goToRegister}>Зареєструватися</a>
                </div>
            </div>
        </div>
    );
};

export default LoginPage;
